structs.string_t:
typedef struct string_t
{
    char *bytes;
    unsigned long size;
} string_t;

functions.new_string:
string_t *new_string(unsigned long size)
{
    string_t *str = malloc(sizeof(string_t));
    str->size = size;
    str->bytes = calloc(size, sizeof(char));
    return str;
}

functions.new_string_from_bytes:
string_t *new_string_from_bytes(const char *bytes)
{
    string_t *str = new_string(strlen(bytes));
    strcpy(str->bytes, bytes);
    return str;
}

functions.string_len:
unsigned long string_len(const string_t *str)
{
    return str->size;
}

functions.string_bytes:
char *string_bytes(const string_t *str)
{
    char *buf = calloc(sizeof(char), str->size);
    strcpy(buf, str->bytes);
    return buf;
}

functions.string_eq:
int string_eq(const string_t *left, const string_t *right)
{
    if (left->size != right->size || strcmp(left->bytes, right->bytes) != 0)
    {
        return 0;
    }
    return 1;
}

functions.string_copy:
string_t *string_copy(const string_t *str)
{
    string_t *copied_str = new_string(str->size);
    strcpy(copied_str->bytes, str->bytes);
    return copied_str;
}

functions.string_concat:
string_t *string_concat(const string_t *first, const string_t *second)
{
    string_t *new_str = new_string(first->size + second->size);
    strcpy(new_str->bytes, strcat(first->bytes, second->bytes));
    return new_str;
}

functions.string_t_is_space_char:
int string_t_is_space_char(char byte)
{
    for (unsigned long idx = 0; idx < strlen(STRING_T_SPACE_CHARS); ++idx)
    {
        if (STRING_T_SPACE_CHARS[idx] == byte)
        {
            return 1;
        }
    }
    return 0;
}

functions.string_substr:
string_t *string_substr(const string_t *str, unsigned long pos, unsigned long len)
{
    string_t *sub_str = new_string(len);
    for (unsigned long idx = 0; idx < len; idx++)
    {
        sub_str->bytes[idx] = str->bytes[pos + idx];
    }
    return sub_str;
}

functions.string_startswith:
int string_startswith(const string_t *str, const char suffix[])
{
    if (str->size < strlen(suffix))
    {
        return 0;
    }
    string_t *exp_suffix = new_string_from_bytes(suffix);
    string_t *str_suffix = string_substr(str, 0, exp_suffix->size);
    int is_suffix = string_eq(str_suffix, exp_suffix);
    string_free(str_suffix);
    string_free(exp_suffix);
    return is_suffix;
}

functions.string_endswith:
int string_endswith(const string_t *str, const char prefix[])
{
    if (str->size < strlen(prefix))
    {
        return 0;
    }
    string_t *exp_prefix = new_string_from_bytes(prefix);
    string_t *str_prefix = string_substr(str, str->size - exp_prefix->size, exp_prefix->size);
    int is_suffix = string_eq(str_prefix, exp_prefix);
    string_free(str_prefix);
    string_free(exp_prefix);
    return is_suffix;
}

functions.string_find:
int string_find(const string_t *str, const char chars[])
{
    string_t *chars_str = new_string_from_bytes(chars);
    if (chars_str->size == 0)
    {
        string_free(chars_str);
        return 0;
    }
    for (unsigned long pos = 0; pos < str->size; ++pos)
    {
        string_t *sub_str = string_substr(str, pos, chars_str->size);
        if (string_eq(sub_str, chars_str) == 1)
        {
            string_free(chars_str);
            string_free(sub_str);
            return (int)pos;
        }
        string_free(sub_str);
    }
    string_free(chars_str);
    return -1;
}

functions.string_strip:
string_t *string_strip(const string_t *str)
{
    unsigned long start_pos = 0;
    for (; start_pos < str->size && string_t_is_space_char(str->bytes[start_pos]); ++start_pos)
        ;
    int end_pos = (int)str->size - 1;
    for (; end_pos >= 0 && string_t_is_space_char(str->bytes[end_pos]); --end_pos)
        ;
    if ((int)start_pos >= end_pos)
    {
        return string_copy(str);
    }
    return string_substr(str, start_pos, end_pos - start_pos + 1);
}

functions.string_split:
string_t **string_split(const string_t *str, unsigned long *arr_size)
{
    unsigned long str_count = 0;
    unsigned long indexes[512];
    if (str->size == 0)
    {
        str_count = 1;
        string_t **str_arr = calloc(str_count, sizeof(string_t));
        str_arr[0] = string_copy(str);
        if (arr_size)
        {
            *arr_size = str_count;
        }
        return str_arr;
    }
    unsigned long start_pos = 0;
    unsigned long pos = 0;
    for (; pos < str->size;)
    {
        if (string_t_is_space_char(str->bytes[pos]))
        {
            indexes[str_count * 2] = start_pos;
            indexes[str_count * 2 + 1] = pos;
            for (; string_t_is_space_char(str->bytes[pos]); pos++)
                ;
            start_pos = pos;
            ++str_count;
        }
        else
        {
            ++pos;
        }
    }
    if (pos != start_pos)
    {
        indexes[str_count * 2] = start_pos;
        indexes[str_count * 2 + 1] = pos;
        ++str_count;
    }
    string_t **str_arr = calloc(str_count, sizeof(string_t));
    for (unsigned long idx = 0; idx < str_count; ++idx)
    {
        unsigned long sub_str_start_pos = indexes[idx * 2];
        unsigned long sub_str_end_pos = indexes[idx * 2 + 1];
        str_arr[idx] = string_substr(str, sub_str_start_pos, sub_str_end_pos - sub_str_start_pos);
    }
    if (arr_size)
    {
        *arr_size = str_count;
    }
    return str_arr;
}

functions.string_split_by:
string_t **string_split_by(const string_t *str, unsigned long *arr_size, const char split_chars[])
{
    unsigned long str_count = 0;
    unsigned long indexes[512];
    string_t *split_str = new_string_from_bytes(split_chars);
    if (str->size <= split_str->size)
    {
        str_count = 1;
        string_t **str_arr = calloc(str_count, sizeof(string_t));
        str_arr[0] = string_copy(str);
        if (arr_size)
        {
            *arr_size = str_count;
        }
        string_free(split_str);
        return str_arr;
    }
    unsigned long start_pos = 0;
    unsigned long pos = 0;
    for (; pos < str->size - split_str->size;)
    {
        string_t *sub_str = string_substr(str, pos, split_str->size);
        if (string_eq(sub_str, split_str) == 1)
        {
            indexes[str_count * 2] = start_pos;
            indexes[str_count * 2 + 1] = pos;
            start_pos = pos + split_str->size;
            ++str_count;
            pos += split_str->size;
        }
        else
        {
            ++pos;
        }
        string_free(sub_str);
    }
    if (pos != start_pos)
    {
        indexes[str_count * 2] = start_pos;
        indexes[str_count * 2 + 1] = pos + 1;
        ++str_count;
    }
    string_t **str_arr = calloc(str_count, sizeof(string_t *));
    for (unsigned long idx = 0; idx < str_count; ++idx)
    {
        unsigned long sub_str_start_pos = indexes[idx * 2];
        unsigned long sub_str_end_pos = indexes[idx * 2 + 1];
        str_arr[idx] = string_substr(str, sub_str_start_pos, sub_str_end_pos - sub_str_start_pos);
    }
    if (arr_size)
    {
        *arr_size = str_count;
    }
    string_free(split_str);
    return str_arr;
}

functions.string_join_arr:
string_t *string_join_arr(const string_t **str_arr, unsigned long arr_size, const char space_chars[])
{
    unsigned long str_size = strlen(space_chars) * (arr_size - 1);
    for (unsigned long idx = 0; idx < arr_size; ++idx)
    {
        str_size += str_arr[idx]->size;
    }
    string_t *join_str = new_string(str_size);
    unsigned long offset = 0;
    for (unsigned long idx = 0; idx < arr_size; ++idx)
    {
        strcpy(join_str->bytes + offset, str_arr[idx]->bytes);
        offset += str_arr[idx]->size;
        if (idx != arr_size - 1)
        {
            strcpy(join_str->bytes + offset, space_chars);
            offset += strlen(space_chars);
        }
    }
    return join_str;
}
